// Included inside the existing app closure by the build. Keeps the Vibe design.
const cloud={user:null,ready:false,loading:true,error:'',people:[],roomRows:[],members:[],messages:[],peer:null,inbox:[],notifications:[],reports:[],blocks:[],likes:[],busy:false,profileStamp:'',saveTimer:null,saveBusy:false,authNotice:'',recoveryNotice:'',pendingMedia:null,older:false,onboarding:{complete:false,step:0,next_step:1},profileData:{details:null,photos:[],prompts:[],completion:null}};
let authScreen='welcome';
let pendingAuth=null;
try{const saved=JSON.parse(sessionStorage.getItem('vibe.pendingAuth')||'null');if(saved&&typeof saved.email==='string'&&Date.now()-saved.at<3600000){pendingAuth=saved;authScreen='verify';}}catch{}
function rememberAuth(){try{if(pendingAuth)sessionStorage.setItem('vibe.pendingAuth',JSON.stringify(pendingAuth));else sessionStorage.removeItem('vibe.pendingAuth');}catch{}}
function showVerification(email,kind='signup',sent=true){pendingAuth={email,kind,at:Date.now(),resendAt:sent?Date.now()+60000:0};rememberAuth();authScreen='verify';cloud.authNotice=sent?t('أرسلنا رمز التحقق إلى بريدك. أدخله هنا لإكمال الدخول.','Check your email and enter the verification code to continue.'):t('أدخل رمز التأكيد من بريدك، أو اضغط إعادة إرسال الرمز.','Enter your email confirmation code, or resend it.');}
async function finishAuth(r={}){if(r?.confirmation_required)return r;pendingAuth=null;rememberAuth();await cloudBoot();if(cloud.error)throw Error('profile_load_failed');if(!cloud.user)throw Error('invalid_session');go(cloud.onboarding?.complete?'home':'onboarding');return r;}

const cloudBaseRender=render,cloudBaseGo=go,cloudBaseProfile=profile,cloudBaseOnboarding=onboarding;
function cloudError(e){const code=e?.code||e?.message||'',status=Number(e?.status||0);const errors={otp_expired:['الرمز غير صحيح أو انتهت صلاحيته. اطلب رمزًا جديدًا.','The code is invalid or expired. Request a new code.'],invalid_code:['أدخل رمز التحقق كاملًا كما وصلك بالبريد.','Enter the complete code from your email.'],profile_load_failed:['تم التحقق، لكن تعذّر تحميل الحساب. أعد تحميل الصفحة.','Verified, but your profile could not load. Reload the page.'],invalid_session:['انتهت جلسة الحساب أو تعذّر إنشاؤها. سجّل الدخول من جديد.','Your account session could not be established. Sign in again.'],invalid_email:['تحقق من عنوان البريد الإلكتروني.','Check your email address.'],sign_in_required:['سجّل الدخول للمتابعة.','Sign in to continue.'],invalid_credentials:['البريد أو كلمة المرور غير صحيحة.','Incorrect email or password.'],email_not_confirmed:['أكد بريدك الإلكتروني أولًا.','Confirm your email first.'],email_address_not_authorized:['إرسال رسالة التأكيد لهذا البريد غير متاح. تواصل مع دعم Vibe.','A confirmation message cannot be sent to this address. Contact Vibe support.'],over_email_send_rate_limit:['تم طلب رسائل كثيرة خلال وقت قصير. انتظر قليلًا ثم حاول.','Too many emails were requested. Wait a moment and try again.'],rate_limited:['طلبات كثيرة؛ حاول بعد قليل.','Too many requests. Try shortly.'],invalid_password:['استخدم كلمة مرور من 8 إلى 128 حرفًا.','Use a password of 8–128 characters.'],weak_password:['اختر كلمة مرور أقوى تحتوي على أحرف وأرقام.','Choose a stronger password with letters and numbers.'],signup_disabled:['إنشاء الحسابات متوقف مؤقتًا. تواصل مع دعم Vibe.','Account creation is temporarily disabled. Contact Vibe support.'],consent_required:['وافق على الشروط والخصوصية وقواعد المجتمع للمتابعة.','Accept the terms, privacy policy and community rules to continue.'],email_exists:['هذا البريد مرتبط بحساب سابق. سجّل الدخول أو استخدم «نسيت كلمة المرور».','This email is already linked to an account. Sign in or reset your password.'],user_already_exists:['هذا البريد مرتبط بحساب سابق. سجّل الدخول أو استخدم «نسيت كلمة المرور».','This email is already linked to an account. Sign in or reset your password.'],forbidden_origin:['إعداد رابط التطبيق غير متطابق مع النسخة المفتوحة. أعد تحميل الرابط الحالي.','This app URL is not accepted by the server. Reload the current deployment.'],invalid_response:['الخادم أعاد استجابة غير صالحة. حاول مرة أخرى.','The server returned an invalid response. Try again.'],request_failed:['تعذّر إكمال طلب الحساب. حاول مرة أخرى.','The account request could not be completed. Try again.'],temporarily_unavailable:['خدمة الحسابات غير متاحة مؤقتًا. حاول بعد قليل.','The account service is temporarily unavailable. Try again shortly.'],unavailable:['خدمة الحسابات غير متاحة مؤقتًا. حاول بعد قليل.','The account service is temporarily unavailable. Try again shortly.']};if(errors[code])return t(...errors[code]);if(status===429)return t('طلبات كثيرة؛ حاول بعد قليل.','Too many requests. Try shortly.');if(status>=500)return t('خدمة الحسابات غير متاحة مؤقتًا. حاول بعد قليل.','The account service is temporarily unavailable. Try again shortly.');return t('تعذّر الاتصال بخدمة الحسابات الآن. حاول مرة أخرى بعد قليل.','The account service could not be reached. Try again shortly.');}
async function cloudAPI(path,method='GET',data){const headers={Accept:'application/json'};let body;if(data instanceof Blob){headers['Content-Type']=data.type;body=data;}else if(data!==undefined){headers['Content-Type']='application/json';body=JSON.stringify(data);}let r;try{r=await fetch('/api/cloud/'+path,{method,headers,body,credentials:'same-origin',cache:'no-store'});}catch(cause){const err=Error('unavailable');err.code='unavailable';err.cause=cause;throw err;}const result=await r.json().catch(()=>({error:'invalid_response'}));if(!r.ok){const err=Error(result.error||'unavailable');err.code=result.error||'unavailable';err.status=r.status;throw err;}return result;}
async function cloudAuthDirect(action,data){return cloudAPI('auth/'+action,'POST',data);}
function cloudGuard(){if(cloud.user)return true;go('auth');toast(t('سجّل الدخول للمتابعة.','Sign in to continue.'));return false;}
const cloudFile=path=>'/api/cloud/file?path='+encodeURIComponent(path);
function cloudPerson(id){return cloud.people.find(p=>p.id===id)||{id,display_name:t('عضو Vibe','Vibe member'),data:{}};}
function cloudPhoto(p){const path=p?.data?.avatar;return typeof path==='string'&&/^[\w/.-]+$/.test(path)?cloudFile(path):'';}
function cloudAvatar(p){return cloudPhoto(p)?`<span class="avatar"><img class="profile-photo" src="${esc(cloudPhoto(p))}" alt=""></span>`:`<span class="avatar av4">${esc((p?.display_name||'V')[0])}</span>`;}
function authLogo(){return `<div class="welcome-logo" aria-label="Vibe"><span>vibe</span><i></i><i></i><i></i></div>`;}
function openAuthForm(mode){authMode=mode;authScreen='form';cloud.authNotice='';render();}
function openAuthPolicy(page){sheetShell(()=>page==='terms'?termsPage():page==='privacy'?privacyPage():communityPage());}
function authWelcome(){return `<section class="vibe-welcome"><button class="welcome-language" ${on(switchLang)}>${t('English','العربية')}</button><div class="welcome-center">${authLogo()}<p>${t('على نفس الموجة.','On the same wavelength.')}</p></div><div class="welcome-actions"><p class="welcome-legal">${t('بإنشاء حساب أو تسجيل الدخول، فإنك توافق على','By creating an account or signing in, you agree to our')} <button ${on(()=>openAuthPolicy('terms'))}>${t('الشروط','Terms')}</button> ${t('وتتعرف على كيفية استخدام بياناتك في','and learn how we use your data in our')} <button ${on(()=>openAuthPolicy('privacy'))}>${t('سياسة الخصوصية','Privacy Policy')}</button> ${t('و','and')} <button ${on(()=>openAuthPolicy('community'))}>${t('قواعد المجتمع','Community Rules')}</button>.</p><button class="welcome-primary" ${on(()=>openAuthForm('signup'))}>${t('إنشاء حساب','Create account')}</button><button class="welcome-secondary" ${on(()=>openAuthForm('login'))}>${t('تسجيل الدخول','Sign in')}</button><button class="welcome-help" ${on(()=>{authScreen='recovery';cloud.recoveryNotice='';render()})}>${t('تواجه مشكلة في الدخول؟','Trouble signing in?')}</button></div></section>`;}
function cloudGate(){return `<section class="auth-wrap"><div class="auth-brand"><div class="logo">vibe</div><h1>${t('مكانك بين ناسك.','Find your kind of people.')}</h1><p>${t('حسابك ومحادثاتك، معك على أجهزتك.','Your profile and conversations, across your devices.')}</p></div><div class="auth-card"><h2>${t('أهلًا بك','Welcome')}</h2><p>${t('سجّل الدخول لاكتشاف المجتمع والمشاركة.','Sign in to discover the community and take part.')}</p><button class="primary" ${on(()=>go('auth'))}>${t('تسجيل الدخول','Sign in')}</button><a class="chip" href="mailto:support@vibe-groups.com">${t('تواصل مع الدعم','Contact support')}</a></div></section>`;}
auth=function(){return `<section class="auth-form-screen"><div class="auth-form-top"><button class="auth-back" aria-label="${t('رجوع','Back')}" ${on(()=>{authScreen='welcome';cloud.authNotice='';render()})}>‹</button><button class="auth-language" ${on(switchLang)}>${t('English','العربية')}</button></div><div class="auth-form-brand">${authLogo()}<h1>${authMode==='signup'?t('ابدأ فايبك','Start your Vibe'):t('أهلًا برجعتك','Welcome back')}</h1><p>${authMode==='signup'?t('أنشئ حسابك وخل فايبك يجمعك بناسك.','Create your account and find your people.'):t('سجّل الدخول وكمل من مكانك.','Sign in and pick up where you left off.')}</p></div><div class="auth-clean-card"><h2>${authMode==='signup'?t('إنشاء حساب','Create account'):t('تسجيل الدخول','Sign in')}</h2>${cloud.authNotice?`<p role="status" class="notice">${esc(cloud.authNotice)}</p>`:''}<form ${on(cloudAuth,'submit')}>${authMode==='signup'?`<label>${t('اسم العرض','Display name')}<input name="name" maxlength="24" required autocomplete="nickname"></label>`:''}<label>${t('البريد الإلكتروني','Email')}<input name="email" type="email" required autocomplete="email" inputmode="email"></label><label>${t('كلمة المرور','Password')}<input name="password" type="password" minlength="8" maxlength="128" required autocomplete="${authMode==='signup'?'new-password':'current-password'}"></label>${authMode==='signup'?`<label class="consent-check"><input type="checkbox" name="accepted" required><span>${t('عمري 18 عامًا أو أكثر وأوافق على الشروط والخصوصية وقواعد المجتمع.','I am 18 or older and agree to the terms, privacy policy and community rules.')}</span></label>`:''}<button class="auth-submit" ${cloud.busy?'disabled':''}>${cloud.busy?t('انتظر…','Please wait…'):authMode==='signup'?t('إنشاء الحساب','Create account'):t('تسجيل الدخول','Sign in')}</button></form><button class="auth-text-link" ${on(()=>openAuthForm(authMode==='login'?'signup':'login'))}>${authMode==='login'?t('جديد في Vibe؟ أنشئ حسابًا','New to Vibe? Create account'):t('لديك حساب؟ سجّل الدخول','Already have an account? Sign in')}</button>${authMode==='login'?`<button type="button" class="auth-text-link" ${cloud.busy?'disabled':''} ${on(loginWithCode)}>${t('الدخول برمز عبر البريد','Sign in with an email code')}</button><button class="auth-text-link subtle" ${on(()=>{authScreen='recovery';cloud.recoveryNotice='';render()})}>${t('نسيت كلمة المرور؟','Forgot password?')}</button>`:''}</div></section>`;};
async function cloudAuth(e){e.preventDefault();if(cloud.busy)return;const f=new FormData(e.target),email=String(f.get('email')||'').trim(),password=String(f.get('password')||''),name=String(f.get('name')||'').trim(),accepted=f.get('accepted')==='on';if(authMode==='signup'&&!accepted){cloud.authNotice=cloudError(Error('consent_required'));render();return;}cloud.busy=true;cloud.authNotice='';const button=e.target.querySelector('button');if(button)button.disabled=true;try{const r=authMode==='signup'?await cloudAuthDirect('signup',{email,password,name,accepted}):await cloudAuthDirect('login',{email,password});if(r.confirmation_required){showVerification(email,'signup');}else{await finishAuth(r);}}catch(err){if(err.message==='email_not_confirmed'||err.code==='email_not_confirmed'){showVerification(email,'signup',false);}else{cloud.authNotice=cloudError(err);}}finally{cloud.busy=false;render();}}
function verificationView(){if(!pendingAuth){authScreen='form';return auth();}return `<section class="auth-form-screen"><div class="auth-form-top"><button class="auth-back" aria-label="${t('تعديل البريد','Change email')}" ${on(()=>{authScreen='form';cloud.authNotice='';render()})}>‹</button><button class="auth-language" ${on(switchLang)}>${t('English','العربية')}</button></div><div class="auth-form-brand">${authLogo()}<h1>${t('أدخل رمز التحقق','Enter verification code')}</h1><p dir="ltr">${esc(pendingAuth.email)}</p></div><div class="auth-clean-card">${cloud.authNotice?`<p role="status" class="notice">${esc(cloud.authNotice)}</p>`:''}<form ${on(verifyAuthCode,'submit')}><label for="auth-code">${t('رمز التحقق من البريد','Email verification code')}</label><input id="auth-code" name="token" type="text" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9٠-٩۰-۹]{6}" minlength="6" maxlength="6" required dir="ltr" class="auth-code" autofocus><button class="auth-submit" ${cloud.busy?'disabled':''}>${cloud.busy?t('جارٍ التحقق…','Verifying…'):t('تأكيد ومتابعة','Verify and continue')}</button></form><button class="auth-text-link" ${cloud.busy?'disabled':''} ${on(resendAuthCode)}>${t('إعادة إرسال الرمز','Resend code')}</button><button class="auth-text-link" ${on(()=>{authScreen='form';cloud.authNotice='';render()})}>${t('تعديل البريد الإلكتروني','Change email')}</button></div></section>`;}
async function verifyAuthCode(e){e.preventDefault();if(cloud.busy||!pendingAuth)return;const token=String(new FormData(e.target).get('token')||'').replace(/[٠-٩]/g,c=>String(c.charCodeAt(0)-1632)).replace(/[۰-۹]/g,c=>String(c.charCodeAt(0)-1776)).trim();if(!/^\d{6}$/.test(token)){cloud.authNotice=cloudError(Error('invalid_code'));render();return;}cloud.busy=true;cloud.authNotice='';render();try{const r=await cloudAuthDirect('verify',{email:pendingAuth.email,token,type:'email'});await finishAuth(r);}catch(err){cloud.authNotice=cloudError(err);}finally{cloud.busy=false;render();}}
async function resendAuthCode(){if(cloud.busy||!pendingAuth)return;const wait=Math.ceil((pendingAuth.resendAt-Date.now())/1000);if(wait>0){cloud.authNotice=t('يمكن إعادة الإرسال بعد '+wait+' ثانية.','You can resend in '+wait+' seconds.');render();return;}cloud.busy=true;render();try{await cloudAuthDirect(pendingAuth.kind==='signup'?'resend':'otp',pendingAuth.kind==='signup'?{email:pendingAuth.email,type:'signup'}:{email:pendingAuth.email});pendingAuth.resendAt=Date.now()+60000;rememberAuth();cloud.authNotice=t('أرسلنا رسالة جديدة. تحقق من البريد الوارد والرسائل غير المرغوب فيها.','New email sent. Check your inbox and spam folder.');}catch(err){cloud.authNotice=cloudError(err);}finally{cloud.busy=false;render();}}
async function loginWithCode(){const input=document.querySelector('input[name="email"]');if(!input?.reportValidity())return;const email=input.value.trim();if(!email||cloud.busy)return;cloud.busy=true;cloud.authNotice='';try{await cloudAuthDirect('otp',{email});showVerification(email,'email');}catch(err){cloud.authNotice=cloudError(err);}finally{cloud.busy=false;render();}}
async function cloudRecover(e){e.preventDefault();if(cloud.busy)return;const email=String(new FormData(e.target).get('email')||'').trim();cloud.busy=true;cloud.recoveryNotice='';render();try{await cloudAuthDirect('recover',{email});cloud.recoveryNotice=t('إذا كان البريد مسجلًا، أرسلنا إليه رابط استعادة آمن.','If this email is registered, we sent it a secure recovery link.');}catch(err){cloud.recoveryNotice=cloudError(err);}finally{cloud.busy=false;render();}}
function cloudRecoveryView(){return `<section class="recovery-screen"><div class="recovery-top"><button class="auth-back" aria-label="${t('رجوع','Back')}" ${on(()=>{authScreen='welcome';cloud.recoveryNotice='';render()})}>‹</button><button class="auth-language" ${on(switchLang)}>${t('English','العربية')}</button></div><div class="recovery-copy">${authLogo()}<h1>${t('خلّنا نرجّعك لحسابك…','Let’s get you back in…')}</h1><form ${on(cloudRecover,'submit')}><label>${t('أدخل بريدك الإلكتروني','Enter email')}<span>${t('أدخل البريد المرتبط بحسابك، وسنرسل لك رابطًا آمنًا لاستعادة الوصول.','Enter the email associated with your account. We’ll send you a secure link to regain access.')}</span><input name="email" type="email" required autocomplete="email" inputmode="email" placeholder="name@example.com"></label>${cloud.recoveryNotice?`<p role="status" class="recovery-notice">${esc(cloud.recoveryNotice)}</p>`:''}<button class="recovery-submit" ${cloud.busy?'disabled':''}>${cloud.busy?t('جارٍ الإرسال…','Sending…'):t('إرسال الرابط','Send email')}</button></form></div></section>`;}
function cloudPassword(){sheetShell(()=>`<h2>${t('كلمة مرور جديدة','New password')}</h2><form ${on(async e=>{e.preventDefault();try{await cloudAPI('auth/password','POST',{password:e.target.password.value});document.querySelector('#create').close();toast(t('تم تحديث كلمة المرور.','Password updated.'));}catch(err){toast(cloudError(err))}},'submit')}><input name="password" type="password" minlength="8" maxlength="128" autocomplete="new-password" required><button class="primary">${t('حفظ','Save')}</button></form>`);}
async function cloudBoot(){cloud.loading=true;try{const hash=new URLSearchParams(location.hash.slice(1));const recovery=hash.get('type')==='recovery'||new URLSearchParams(location.search).get('recovery')==='1';if(hash.has('access_token')){await cloudAPI('auth/callback','POST',{access_token:hash.get('access_token'),refresh_token:hash.get('refresh_token')});history.replaceState(null,'',location.pathname);}
 const session=await cloudAPI('auth/session');cloud.user=session.user;if(cloud.user){const p=(await cloudAPI('profile')).profile;displayName=p.display_name;profileBio=p.bio;const d=p.data||{};profileEmoji=String(d.emoji||'');profilePhoto=d.avatar?cloudFile(d.avatar):'';galleryPhotos=(Array.isArray(d.gallery)?d.gallery:[]).slice(0,9).map(cloudFile);useGalleryPhoto=!!d.useGallery;profileLink=safeProfileLink(d.link||'')||'';profilePrompts=(Array.isArray(d.prompts)?d.prompts:[]).filter(x=>Number.isInteger(x.id)&&promptChoices[x.id]&&typeof x.answer==='string').slice(0,6);for(const [set,values]of [[vibePicks,d.nature],[interestPicks,d.interests],[typePicks,d.types]]){set.clear();for(const v of Array.isArray(values)?values:[])if(Number.isInteger(v)&&v>=0&&v<200)set.add(v);}preferences={...defaultSettings(),...(await cloudAPI('settings')).settings};communityAccepted=true;await cloudLoadLists();cloud.profileStamp=cloudSnapshot();cloud.ready=true;if(recovery)cloudPassword();}else{cloud.ready=true;cloud.people=[];cloud.roomRows=[];}cloud.error='';}catch(e){cloud.error=cloudError(e);}finally{cloud.loading=false;render();}}
async function cloudLoadLists(){const [r,p,l,b,reports,inbox]=await Promise.all([cloudAPI('rooms'),cloudAPI('people'),cloudAPI('likes'),cloudAPI('blocks'),cloudAPI('reports'),cloudAPI('inbox')]);cloud.roomRows=r.rooms;cloud.people=p.people;cloud.likes=l.items.map(x=>x.room_id);cloud.blocks=b.items.map(x=>x.blocked_id);cloud.reports=reports.reports;cloud.inbox=inbox.messages;rooms.splice(0,rooms.length,...cloud.roomRows.map(r=>({id:r.id,title:r.title,category:r.category,type:r.kind,own:r.owner_id===cloud.user.id,desc:[cloudPerson(r.owner_id).display_name,cloudPerson(r.owner_id).display_name],names:[],count:0})));}
function cloudOpenFeature(kind){if(kind==='cinema'){location.assign('/cinema.html');return;}const found=cloud.roomRows.find(r=>r.kind===kind);if(found)join(found.id);else openCreate(kind);}function cloudPeopleRail(){return cloud.people.slice(0,3).map((p,i)=>`<div class="friend">${cloudAvatar(p)}<div class="info"><strong>${esc(p.display_name)}</strong><small>${esc(p.bio||t('عضو في مجتمع Vibe','Vibe community member'))}</small></div><button ${on(()=>cloudOpenPeer(p.id))}>${t('مراسلة','Message')}</button></div>`).join('')||`<p class="muted">${t('سيظهر الأعضاء هنا عند انضمامهم.','Members will appear here as they join.')}</p>`;}home=function(){if(!cloud.user)return cloudGate();const visible=rooms.filter(r=>(!filter||r.category===filter)).sort((a,b)=>roomScore(b)-roomScore(a));return `<div class="intro"><div><h1>${t('مساء الفايب،','Good vibes,')} ${esc(userName())} ✨</h1><p>${t('ناس تشبهك، وسوالف على مزاجك.','Your people. Your kind of conversation.')}</p></div><button class="primary" ${on(()=>openCreate())}><span class="icon">＋</span>${t('اصنع فايبك','Create a vibe')}</button></div><div class="content-grid"><section><div class="hero"><div class="hero-copy"><span class="live">${t('على نفس الموجة','ON THE SAME WAVELENGTH')}</span><h2>${t('ليلتك، بأكثر من فايب.','One night. Every kind of vibe.')}</h2><p>${t('سولف، العب، أو اجمع الشلة على فيلم.','Talk, play, or bring the crew together for a film.')}</p><button class="primary" ${on(()=>visible[0]?join(visible[0].id):openCreate('voice'))}>${t('انضم للسّهرة','Join the night')} ←</button></div><div class="hero-art" aria-hidden="true"><div class="wave">${'<i></i>'.repeat(7)}</div></div></div><div class="feature-shortcuts">${[['⚡','flash'],['▷','cinema'],['🎮','game'],['◉','echo']].map(([icon,type])=>`<button ${on(()=>cloudOpenFeature(type))}><span>${icon}</span>${t(...types[type])}${['flash','cinema'].includes(type)?'<small>PLUS</small>':''}</button>`).join('')}</div><div class="section-title"><h2>${t('اكتشف الرومات','Discover rooms')} ✦</h2><button class="chip" ${on(async()=>{try{await cloudLoadLists();render()}catch(e){toast(cloudError(e))}})}>${t('تحديث','Refresh')}</button></div><div class="filters">${categories.map((c,i)=>`<button class="chip ${filter===i?'active':''}" aria-pressed="${filter===i}" ${on(()=>{filter=i;render()})}>${t(...c)}</button>`).join('')}</div><div class="rooms">${visible.map(card).join('')||`<p class="notice">${t('لا توجد رومات بعد. أنشئ أول روم وادعُ أصحابك.','No rooms yet. Create the first and invite your friends.')}</p>`}</div></section><aside class="right-rail">${moodUI()}<div class="aside-card"><h3>${t('أصحابك هنا','Friends are here')}</h3>${cloudPeopleRail()}</div><div class="mini-event"><span class="eyebrow">VIBE+ ✦</span><h4>${t('ارفع مستوى حضورك','Turn up your presence')}</h4><p>${t('فلاش، سينما، ألعاب، وبودكاست.','Flash, cinema, games and podcasts.')}</p><button class="primary" ${on(()=>go('plus'))}>${t('اكتشف المزايا','Explore benefits')}</button></div></aside></div>`;};
openCreate=function(selected='voice'){if(!cloudGuard())return;sheetShell(()=>`<h2>${t('أنشئ رومًا','Create a room')}</h2><form ${on(createRoom,'submit')}><label>${t('اسم الروم','Room name')}<input name="title" required maxlength="60"></label><label>${t('النوع','Type')}<select name="kind">${Object.entries(types).map(([k,v])=>`<option value="${k}" ${k===selected?'selected':''}>${t(...v)}</option>`).join('')}</select></label><label>${t('التصنيف','Category')}<select name="category">${categories.slice(1).map((c,i)=>`<option value="${i+1}">${t(...c)}</option>`).join('')}</select></label><p class="notice">${t('تتوفر الدردشة والوسائط. البث الصوتي المباشر غير مفعّل بعد.','Chat and media are available. Live voice streaming is not enabled yet.')}</p><button class="primary">${t('إنشاء','Create')}</button></form>`);};
createRoom=async function(e){e.preventDefault();const f=new FormData(e.target);try{const r=await cloudAPI('rooms','POST',{title:String(f.get('title')||'').trim(),kind:f.get('kind'),category:Number(f.get('category'))});document.querySelector('#create').close();await cloudLoadLists();await join(r.room.id);}catch(err){toast(cloudError(err));}};
join=async function(id){if(!cloudGuard())return;try{await cloudAPI('membership?room='+encodeURIComponent(id),'POST');current=rooms.find(r=>r.id===id);if(!current){await cloudLoadLists();current=rooms.find(r=>r.id===id);}if(!current)return;view='room';cloud.messages=[];cloud.older=false;await cloudMessages();render();}catch(e){toast(cloudError(e));}};
async function cloudMessages(older=false){if(!cloud.user||view!=='room'&&view!=='chats')return;const roomId=view==='room'?current?.id:null,peerId=view==='chats'?cloud.peer:null;if(!roomId&&!peerId)return;const query=roomId?'room='+roomId:'peer='+peerId;const before=older&&cloud.messages.length?'&before='+encodeURIComponent(cloud.messages[0].created_at):'';const data=await cloudAPI('messages?'+query+before);if((view==='room'?current?.id:null)!==roomId||(view==='chats'?cloud.peer:null)!==peerId)return;const rows=data.messages.reverse();cloud.messages=older?[...rows,...cloud.messages]:rows;cloud.older=older?cloud.older||rows.length===60:rows.length===60;if(roomId){cloud.members=(await cloudAPI('membership?room='+roomId)).members;}}
function cloudMessageList(){return `<div class="messages">${cloud.older?`<button class="chip" ${on(async()=>{try{await cloudMessages(true);render()}catch(e){toast(cloudError(e))}})}>${t('رسائل أقدم','Older messages')}</button>`:''}${cloud.messages.map(m=>`<article class="bubble ${m.author_id===cloud.user.id?'self':''}"><small>${esc(m.author_id===cloud.user.id?userName():cloudPerson(m.author_id).display_name)} · ${esc(new Date(m.created_at).toLocaleTimeString(lang,{hour:'2-digit',minute:'2-digit'}))}</small>${m.kind==='text'?`<p>${linkMessage(m.body)}</p>`:m.kind==='photo'?`<a href="${esc(cloudFile(m.object_path))}" target="_blank" rel="noopener"><img class="chat-photo" src="${esc(cloudFile(m.object_path))}" alt="${t('صورة مشتركة','Shared photo')}" loading="lazy"></a>`:`<audio controls preload="none" src="${esc(cloudFile(m.object_path))}"></audio>`}<div><button class="member-report" ${on(()=>openReport('message',m.id))}>${t('إبلاغ','Report')}</button>${m.author_id===cloud.user.id?`<button class="member-report" ${on(async()=>{try{await cloudAPI('messages?id='+m.id,'DELETE');await cloudMessages();render()}catch(e){toast(cloudError(e))}})}>${t('حذف','Delete')}</button>`:''}</div></article>`).join('')||`<p class="muted">${t('ابدأ أول رسالة.','Start the conversation.')}</p>`}</div>`;}
room=function(){if(!current)return home();return `<section class="room-view"><div class="intro"><div><span class="category">${t(...types[current.type])}</span><h1>${esc(textTitle(current))}</h1></div><button class="chip" ${on(async()=>{try{await cloudAPI('membership?room='+current.id,'DELETE');go('home')}catch(e){toast(cloudError(e))}})}>${t('مغادرة','Leave')}</button></div><div class="controls"><button class="chip" ${on(()=>cloudLike(current.id))}>♡ ${cloud.likes.includes(current.id)?t('إلغاء الإعجاب','Unlike'):t('إعجاب','Like')}</button><button class="chip" ${on(()=>openReport('room',current.id))}>${t('إبلاغ','Report')}</button>${current.own?`<button class="control leave" ${on(cloudCloseRoom)}>${t('إغلاق الروم','Close room')}</button>`:''}</div><div class="speakers">${cloud.members.map(m=>`<button class="speaker" ${on(()=>{if(m.user_id!==cloud.user.id)cloudOpenPeer(m.user_id)})}>${cloudAvatar(m.vibe_profiles)}<span>${esc(m.vibe_profiles?.display_name||'Vibe')}</span></button>`).join('')}</div><p class="notice">${t('هذه قائمة المنضمين وليست مؤشر اتصال مباشر. البث الصوتي المباشر غير مفعّل؛ يمكنك إرسال رسائل صوتية.','This is the joined-member list, not live presence. Live voice is not enabled; voice messages are available.')}</p>${current.type==='cinema'?cinema():current.type==='game'?games():current.type==='echo'?echo():''}<div class="message-panel">${cloudMessageList()}${sendForm('sendRoom')}${cloudMediaStatus()}</div></section>`;};
function cloudCloseRoom(){sheetShell(()=>`<h2>${t('إغلاق الروم وحذف رسائله؟','Close this room and delete its messages?')}</h2><button class="control leave" ${on(async()=>{try{await cloudAPI('rooms?id='+current.id,'DELETE');document.querySelector('#create').close();current=null;await cloudLoadLists();view='home';render()}catch(e){toast(cloudError(e))}})}>${t('تأكيد الإغلاق','Confirm close')}</button>`);}
async function cloudLike(id){try{await cloudAPI('likes?id='+id,cloud.likes.includes(id)?'DELETE':'POST');cloud.likes=(await cloudAPI('likes')).items.map(x=>x.room_id);render()}catch(e){toast(cloudError(e))}}
likesPage=function(){if(!cloud.user)return cloudGate();return `<h1>${t('الرومات المفضلة','Favorite rooms')}</h1><div class="rooms">${cloud.roomRows.filter(r=>cloud.likes.includes(r.id)).map(r=>`<button class="room-card" ${on(()=>join(r.id))}><h3>${esc(r.title)}</h3></button>`).join('')||`<p>${t('لا توجد رومات مفضلة.','No favorites yet.')}</p>`}</div>`;};
async function cloudOpenPeer(id){if(!cloudGuard())return;cloud.peer=id;chatPerson=id;view='chats';cloud.messages=[];cloud.older=false;try{await cloudMessages();render()}catch(e){toast(cloudError(e))}}
chats=function(){if(!cloud.user)return cloudGate();return `<div class="intro"><h1>${t('المحادثات','Conversations')}</h1><button class="chip" ${on(async()=>{try{await cloudLoadLists();render()}catch(e){toast(cloudError(e))}})}>${t('تحديث الأعضاء','Refresh members')}</button></div><form class="send-form" ${on(async e=>{e.preventDefault();try{cloud.people=(await cloudAPI('people?q='+encodeURIComponent(e.target.search.value))).people;render()}catch(err){toast(cloudError(err))}},'submit')}><input name="search" maxlength="40" placeholder="${t('ابحث باسم العضو','Search member name')}" aria-label="${t('بحث الأعضاء','Member search')}"><button class="primary">${t('بحث','Search')}</button></form><div class="message-panel chat-layout"><div class="chat-list">${cloud.people.filter(p=>!cloud.blocks.includes(p.id)).map(p=>`<button class="chat-item ${cloud.peer===p.id?'active':''}" ${on(()=>cloudOpenPeer(p.id))}>${cloudAvatar(p)}<span><strong>${esc(p.display_name)}</strong><small>${esc(cloud.inbox.find(m=>m.author_id===p.id||m.recipient_id===p.id)?.body?.slice(0,50)||p.bio||'')}</small></span></button>`).join('')||`<p class="notice">${t('لا يوجد أعضاء آخرون بعد.','No other members yet.')}</p>`}</div><div class="conversation">${cloud.peer?`<div class="chat-heading">${esc(cloudPerson(cloud.peer).display_name)}<button class="chip" ${on(()=>openReport('user',cloud.peer))}>${t('إبلاغ / حظر','Report / block')}</button></div>${cloudMessageList()}${sendForm('sendChat')}${cloudMediaStatus()}`:`<p class="notice">${t('اختر عضوًا لبدء محادثة.','Choose a member to start a conversation.')}</p>`}</div></div>`;};
async function cloudSend(e,handler){e.preventDefault();if(!cloudGuard()||cloud.busy)return;const input=e.target.message,text=input.value.trim(),target=handler==='sendRoom'?current?.id:cloud.peer;if(!text||text.length>2000||!target)return;cloud.busy=true;try{await cloudAPI('messages','POST',{body:text,...(handler==='sendRoom'?{room_id:target}:{recipient_id:target})});delete chatDrafts[draftKey(handler)];input.value='';await cloudMessages();render();document.querySelector('.messages')?.scrollTo(0,999999);}catch(err){toast(cloudError(err));}finally{cloud.busy=false;}}
sendChat=e=>cloudSend(e,'sendChat');sendRoom=e=>cloudSend(e,'sendRoom');
plusGate=function(){return cloudGuard()};
function cloudMediaStatus(){return cloud.pendingMedia?`<p role="status" class="notice">${cloud.pendingMedia.uploading?t('جارٍ رفع الوسائط…','Uploading media…'):t('تعذّر إرسال الوسائط. يمكنك إعادة المحاولة.','Media could not be sent. You can retry.')}</p>${!cloud.pendingMedia.uploading?`<button class="chip" ${on(cloudRetryMedia)}>${t('إعادة الإرسال','Retry upload')}</button><button class="chip" ${on(()=>{URL.revokeObjectURL(cloud.pendingMedia.url);cloud.pendingMedia=null;render()})}>${t('إلغاء','Cancel')}</button>`:''}`:'';}
sendAttachment=function(handler){if(!attachment||cloud.pendingMedia){toast(t('أكمل إرسال الملف السابق أولًا.','Finish the previous upload first.'));return;}cloud.pendingMedia={...attachment,handler,uploading:false};attachment=null;cloudRetryMedia();};
async function cloudRetryMedia(){const item=cloud.pendingMedia;if(!item||item.uploading)return;item.uploading=true;render();try{const blob=await (await fetch(item.url)).blob();const scope=item.handler==='sendRoom'?'room':'dm';const up=await cloudAPI('upload?scope='+scope+'&target='+item.target,'POST',blob);await cloudAPI('messages','POST',{kind:item.kind,object_path:up.path,...(scope==='room'?{room_id:item.target}:{recipient_id:item.target})});URL.revokeObjectURL(item.url);cloud.pendingMedia=null;await cloudMessages();}catch(e){item.uploading=false;toast(cloudError(e));}finally{render();}}
function cloudSnapshot(){return JSON.stringify({display_name:displayName,bio:profileBio,avatar:profilePhoto,gallery:galleryPhotos,emoji:profileEmoji,link:profileLink,prompts:profilePrompts,useGallery:useGalleryPhoto,nature:[...vibePicks],interests:[...interestPicks],types:[...typePicks],preferences});}
async function cloudPersist(){if(!cloud.user||!cloud.ready||cloud.saveBusy||editDraft)return;const stamp=cloudSnapshot();if(stamp===cloud.profileStamp)return;cloud.saveBusy=true;try{const upload=async url=>{if(!url)return '';if(url.startsWith('/api/cloud/file?path='))return new URL(url,location.origin).searchParams.get('path');if(!url.startsWith('blob:'))return '';const blob=await (await fetch(url)).blob();return (await cloudAPI('upload?scope=profile&target='+cloud.user.id,'POST',blob)).path;};const avatarPath=await upload(profilePhoto),gallery=await Promise.all(galleryPhotos.map(upload));const data={avatar:avatarPath,gallery,emoji:profileEmoji,link:profileLink,prompts:profilePrompts,useGallery:useGalleryPhoto,nature:[...vibePicks],interests:[...interestPicks],types:[...typePicks]};await cloudAPI('profile','PATCH',{display_name:displayName||'Vibe member',bio:profileBio,data});await cloudAPI('settings','POST',preferences);cloud.profileStamp=stamp;const note=document.querySelector('#cloud-save-state');if(note)note.textContent=t('تم الحفظ في حسابك','Saved to your account');}catch(e){toast(t('لم تُحفظ تعديلات الملف بعد.','Profile changes have not been saved yet.')+' '+cloudError(e));}finally{cloud.saveBusy=false;}}
const oldSaveProfile=saveProfileEdit;saveProfileEdit=function(){oldSaveProfile();cloudPersist();};
profile=function(){if(!cloud.user)return cloudGate();return cloudBaseProfile()+`<div class="controls"><button class="primary" ${on(async()=>{await cloudPersist();render()})}>${t('حفظ الملف في حسابي','Save profile to account')}</button><span id="cloud-save-state" role="status">${cloudSnapshot()===cloud.profileStamp?t('تم الحفظ','Saved'):t('تعديلات غير محفوظة','Unsaved changes')}</span><button class="chip" ${on(cloudLogout)}>${t('تسجيل الخروج','Sign out')}</button></div>`;};
onboarding=function(){return cloudBaseOnboarding().replace(t('تخصيص لهذه الجلسة فقط؛ لا يُنشأ حساب فعلي.','Personalization for this session only. No real account is created.'),t('تُحفظ اختياراتك في حسابك.','Your choices are saved to your account.'));};
settingsPage=function(){if(!cloud.user)return cloudGate();return `<section class="settings-page"><h1>${t('الإعدادات','Settings')}</h1><article class="aside-card"><h2>${t('الحساب','Account')}</h2><p dir="ltr">${esc(cloud.user.email||'')}</p><button class="chip" ${on(cloudPassword)}>${t('تغيير كلمة المرور','Change password')}</button><button class="chip" ${on(cloudLogout)}>${t('تسجيل الخروج','Sign out')}</button></article><article class="aside-card"><h2>${t('المظهر والاهتمامات','Appearance & interests')}</h2>${settingSelect('appearance','المظهر','Appearance',[['dark','داكن','Dark'],['light','فاتح','Light']])}<button class="chip" ${on(()=>{onboardingStep=0;go('onboarding')})}>${t('تعديل الاهتمامات','Edit interests')}</button><button class="primary" ${on(cloudPersist)}>${t('حفظ الإعدادات','Save settings')}</button></article><button class="chip" ${on(()=>go('safety'))}>${t('الحظر والبلاغات','Blocks & reports')}</button><button class="chip" ${on(()=>go('account'))}>${t('إدارة الحساب','Manage account')}</button></section>`;};
async function cloudLogout(){try{await cloudPersist();await cloudAPI('auth/logout','POST',{});location.reload();}catch(e){toast(cloudError(e));}}
openReport=function(kind,id){if(!cloudGuard())return;sheetShell(()=>`<h2>${t('إبلاغ','Report')}</h2><p>${t('يُحفظ البلاغ لإدارة Vibe. لا توجد خدمة طوارئ أو ضمان مراجعة فورية.','Reports are saved for Vibe administrators. This is not an emergency service or a promise of immediate review.')}</p><form ${on(async e=>{e.preventDefault();try{await cloudAPI('reports','POST',{target_kind:kind,target_id:String(id),reason:e.target.reason.value,details:e.target.details.value});cloud.reports=(await cloudAPI('reports')).reports;document.querySelector('#create').close();toast(t('تم استلام البلاغ.','Report received.'));}catch(err){toast(cloudError(err))}},'submit')}><label>${t('السبب','Reason')}<select name="reason">${reportReasons.map(x=>`<option>${esc(t(...x))}</option>`).join('')}</select></label><textarea name="details" maxlength="2000" aria-label="${t('التفاصيل','Details')}"></textarea><button class="primary">${t('إرسال البلاغ','Submit report')}</button></form>${kind==='user'?`<button class="control leave" ${on(()=>blockUser(id))}>${t('حظر العضو','Block member')}</button>`:''}`);};
blockUser=async function(id){try{await cloudAPI('blocks?id='+id,'POST');cloud.blocks.push(id);cloud.peer=null;cloud.messages=[];document.querySelector('#create').close();await cloudLoadLists();render();toast(t('تم الحظر.','Member blocked.'));}catch(e){toast(cloudError(e))}};
unblockUser=async function(id){try{await cloudAPI('blocks?id='+id,'DELETE');await cloudLoadLists();render()}catch(e){toast(cloudError(e))}};
safetyPage=function(){if(!cloud.user)return cloudGate();return `<section class="policy-page"><h1>${t('الأمان والمساعدة','Safety & help')}</h1><h2>${t('المحظورون','Blocked members')}</h2>${cloud.blocks.map(id=>`<div class="history"><span>${esc(cloudPerson(id).display_name)}</span><button class="chip" ${on(()=>unblockUser(id))}>${t('إلغاء الحظر','Unblock')}</button></div>`).join('')||`<p>${t('لا يوجد حظر.','No blocked members.')}</p>`}<h2>${t('بلاغاتك وطلبات الدعم','Your reports & support requests')}</h2>${cloud.reports.map(r=>`<article class="aside-card"><strong>${esc(r.reason)}</strong><p>${esc(r.details)}</p><small>${esc(r.status)} · ${esc(new Date(r.created_at).toLocaleDateString())}</small></article>`).join('')||`<p>${t('لا توجد طلبات.','No requests yet.')}</p>`}</section>`;};
supportPage=function(){if(!cloud.user)return cloudGate();return `<section class="policy-page"><h1>${t('دعم Vibe','Vibe support')}</h1><p>${t('أرسل طلبك ليُحفظ لدى إدارة Vibe، أو تواصل عبر البريد. الرد الآلي بالذكاء الاصطناعي غير مفعّل بعد.','Save a request for Vibe administrators or contact us by email. AI replies are not enabled yet.')}</p><a href="mailto:support@vibe-groups.com">support@vibe-groups.com</a><form ${on(async e=>{e.preventDefault();try{await cloudAPI('reports','POST',{target_kind:'support',target_id:'',reason:e.target.subject.value,details:e.target.details.value});e.target.reset();cloud.reports=(await cloudAPI('reports')).reports;toast(t('تم حفظ طلبك.','Your request was saved.'));}catch(err){toast(cloudError(err))}},'submit')}><label>${t('الموضوع','Subject')}<input name="subject" required maxlength="100"></label><label>${t('كيف نساعدك؟','How can we help?')}<textarea name="details" required maxlength="2000" rows="5"></textarea></label><button class="primary">${t('إرسال الطلب','Send request')}</button></form></section>`;};
checkSupport=function(){};
accountPage=function(){if(!cloud.user)return cloudGate();return `<section class="policy-page"><h1>${t('إدارة الحساب','Account management')}</h1><p dir="ltr">${esc(cloud.user.email||'')}</p><button class="chip" ${on(cloudPassword)}>${t('تغيير كلمة المرور','Change password')}</button><button class="chip" ${on(cloudLogout)}>${t('تسجيل الخروج','Sign out')}</button><h2>${t('طلب حذف الحساب','Request account deletion')}</h2><p>${t('الحذف المباشر غير مفعّل بعد. يمكنك إرسال طلب حذف لإدارة Vibe؛ إرسال الطلب لا يحذف البيانات فورًا.','Direct deletion is not enabled yet. You can submit a deletion request to Vibe administrators; submission does not immediately delete data.')}</p><button class="control leave" ${on(async()=>{try{await cloudAPI('reports','POST',{target_kind:'support',target_id:cloud.user.id,reason:'Account deletion request',details:'The signed-in user requests deletion of their account and associated data.'});toast(t('تم حفظ طلب الحذف للمراجعة. حسابك ما زال قائمًا.','Deletion request saved for review. Your account remains active.'));}catch(e){toast(cloudError(e))}})}>${t('إرسال طلب حذف','Submit deletion request')}</button></section>`;};

privacyPage=function(){return `<section class="policy-page"><h1>${t('الخصوصية','Privacy')}</h1><p>${t('يحفظ Vibe بريد حسابك وملفك ورسائلك وملفاتك وبلاغاتك في الخدمات المرتبطة بالتطبيق. قاعدة Supabase الحالية في أيرلندا. بيانات جلسات السينما الحالية تبقى في خدمة استضافة الموقع.','Vibe stores account email, profiles, messages, uploads and reports in connected services. The current Supabase database is in Ireland. Existing cinema-session data remains with the website hosting service.')}</p><p>${t('الملف الشخصي ظاهر للأعضاء المسجلين. الرسائل الخاصة متاحة لطرفي المحادثة وفق صلاحيات التطبيق؛ وليست مشفرة من طرف إلى طرف. يستطيع مشغّل الخدمة الوصول إداريًا إلى البيانات.','Profiles are visible to signed-in members. Direct messages are limited to their participants by access policies; they are not end-to-end encrypted. Service operators retain administrative data access.')}</p><p>${t('يمكنك طلب حذف حسابك من إدارة الحساب. قد تبقى نسخ لدى المستلمين أو في النسخ الاحتياطية وفق سياسة مزود الخدمة. لا ترسل كلمات مرور أو معلومات دفع في المحادثات.','You can request account deletion in Account management. Copies may remain with recipients or provider backups. Do not send passwords or payment details in chats.')}</p><a href="mailto:support@vibe-groups.com">support@vibe-groups.com</a></section>`;};
// Existing legal copy describing all data as a local demo no longer applies.
termsPage=function(){return `<section class="policy-page"><h1>${t('شروط الاستخدام','Terms of use')}</h1><p>${t('Vibe مخصص للبالغين 18 عامًا فأكثر. أنت مسؤول عن المحتوى الذي تشاركه وحقوق استخدامه، وعن حماية حسابك. يُمنع التحرش والاحتيال والتهديد ونشر بيانات الآخرين دون إذن أو مشاركة محتوى غير قانوني.','Vibe is for adults aged 18 and over. You are responsible for your content, the rights to share it, and account security. Harassment, fraud, threats, unauthorized personal-data disclosure and illegal content are prohibited.')}</p><p>${t('المزايا المدفوعة غير مفعّلة. البث الصوتي المباشر وتسجيل Google وApple والدعم الذكي تحتاج إعدادًا إضافيًا. لا يوجد ضمان لتوافر الخدمة أو زمن معالجة البلاغات.','Paid features are not enabled. Live voice, Google and Apple sign-in and AI support require additional setup. Service availability and report response times are not guaranteed.')}</p><a href="mailto:support@vibe-groups.com">support@vibe-groups.com</a></section>`;};
friends=function(){return cloud.people.slice(0,5).map(p=>`<button class="friend" ${on(()=>cloudOpenPeer(p.id))}>${cloudAvatar(p)}${esc(p.display_name)}</button>`).join('');};
go=function(v){if(['profile','chats','edit','settings','onboarding','account','safety','support','likes'].includes(v)&&!cloud.user)v='auth';if(view==='onboarding'||view==='settings')cloudPersist();if(v!==view){stopNote();cloud.messages=[];}cloudBaseGo(v);if(v==='chats'&&cloud.peer)cloudMessages().then(()=>render()).catch(e=>toast(cloudError(e)));};
render=function(){document.body.classList.toggle('auth-only',!cloud.user);if(cloud.loading){app.innerHTML=`<section class="auth-loading">${authLogo()}<p role="status">${t('جارٍ تحميل حسابك…','Loading your account…')}</p></section>`;return;}if(cloud.error){handlerScope='app';handlerMaps.app.clear();app.innerHTML=`<section class="auth-wrap"><p role="alert">${esc(cloud.error)}</p><button class="primary" ${on(cloudBoot)}>${t('إعادة المحاولة','Retry')}</button></section>`;return;}if(!cloud.user&&cloud.ready){handlerScope='app';handlerMaps.app.clear();document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';document.title=t('فايب — على نفس الموجة','Vibe — On the same wavelength');app.innerHTML=authScreen==='verify'?verificationView():authScreen==='form'?auth():authScreen==='recovery'?cloudRecoveryView():authWelcome();return;}const focus=document.activeElement,wasComposer=focus?.name==='message',selection=wasComposer?focus.selectionStart:null;cloudBaseRender();const label=document.querySelector('.demo');if(label)label.textContent=t('نسخة تجريبية متصلة','Connected beta');const sign=document.querySelector('.signin-link');if(sign){sign.textContent=cloud.user?t('الحساب','Account'):t('دخول','Sign in');sign.onclick=e=>{e.stopPropagation();go(cloud.user?'profile':'auth')};}if(wasComposer){const input=document.querySelector('input[name="message"]');input?.focus();try{input?.setSelectionRange(selection,selection)}catch{}}
 if(cloud.user&&cloud.ready&&!editDraft&&cloudSnapshot()!==cloud.profileStamp){clearTimeout(cloud.saveTimer);cloud.saveTimer=setTimeout(cloudPersist,1000);}
};
setInterval(async()=>{if(!cloud.user||document.hidden||noteRecording||noteBusy||cloud.pendingMedia||document.querySelector('#create').open||[...document.querySelectorAll('audio,video')].some(x=>!x.paused))return;if(view==='room'||view==='chats'&&cloud.peer){try{const before=JSON.stringify(cloud.messages);await cloudMessages();if(before!==JSON.stringify(cloud.messages))render();}catch{}}},5000);
window.addEventListener('pageshow',e=>{if(e.persisted)cloudBoot();});

/* Connected profile, onboarding, theme and conversation experience. */
const cloudOriginalBoot=cloudBoot,cloudOriginalGo=go;
async function cloudProfileBundle(){const b=await cloudAPI('profile');cloud.profileData={details:b.details||null,photos:b.photos||[],prompts:b.prompts||[],completion:b.completion||null};return b;}
cloudBoot=async function(){await cloudOriginalBoot();if(!cloud.user||cloud.error)return;try{const [bundle,onboarding,notifications]=await Promise.all([cloudProfileBundle(),cloudAPI('onboarding'),cloudAPI('notifications')]);cloud.onboarding=onboarding.status||cloud.onboarding;cloud.notifications=notifications.items||[];const d=bundle.profile?.data||{};if(bundle.photos?.length){galleryPhotos=bundle.photos.map(x=>cloudFile(x.object_path));profilePhoto=galleryPhotos[0]||profilePhoto;}if(bundle.prompts?.length)profilePrompts=bundle.prompts.map((x,i)=>({id:i,question:x.question,answer:x.answer}));if(!cloud.onboarding.complete){onboardingStep=Math.max(0,Math.min(2,(cloud.onboarding.next_step||1)-1));view='onboarding';}applyAppearance();}catch(e){cloud.error=cloudError(e);}finally{render();}};
go=function(v){if(cloud.user&&!cloud.onboarding.complete&&!['onboarding','auth','terms','privacy','community'].includes(v))v='onboarding';cloudOriginalGo(v);};
function cloudToggleSet(set,i){set.has(i)?set.delete(i):set.add(i);render();}
async function cloudOnboardingNext(){const picks=onboardingStep===0?vibePicks:interestPicks;if(onboardingStep<2&&!picks.size)return toast(t('اختر واحدًا على الأقل.','Choose at least one.'));if(onboardingStep===1&&!typePicks.size)return toast(t('اختر سمة واحدة على الأقل.','Choose at least one personality trait.'));cloud.busy=true;render();try{if(onboardingStep===0)await cloudAPI('onboarding','POST',{step:1,values:[...vibePicks]});else if(onboardingStep===1)await cloudAPI('onboarding','POST',{step:2,values:[...interestPicks],types:[...typePicks]});else{await cloudPersist();const r=await cloudAPI('onboarding','POST',{step:3});cloud.onboarding=r.status||{complete:true,step:3,next_step:null};}if(onboardingStep<2){onboardingStep++;}else{cloud.onboarding.complete=true;await cloudProfileBundle();view='profile';toast(t('تم حفظ فايبك في حسابك.','Your vibe is saved to your account.'));}}catch(e){toast(cloudError(e));}finally{cloud.busy=false;render();}}
onboarding=function(){const titles=[t('اختر فايب الطبيعة الذي يشبهك','Choose the nature vibe that feels like you'),t('اهتماماتك وشخصيتك','Your interests and personality'),t('لمستك الأخيرة','Your finishing touch')],options=onboardingStep===0?natureOptions:interestOptions,picks=onboardingStep===0?vibePicks:interestPicks;return `<section class="setup-page connected-onboarding"><span class="eyebrow">VIBE SETUP · ${onboardingStep+1}/3</span><div class="setup-progress">${[0,1,2].map(i=>`<span class="${i<=onboardingStep?'active':''}"></span>`).join('')}</div><h1>${titles[onboardingStep]}</h1><p class="muted">${t('تُحفظ اختياراتك بأمان في حسابك وتُستخدم لتخصيص اقتراحاتك.','Your choices are securely saved to your account and personalize recommendations.')}</p>${onboardingStep<2?`<div class="setup-options ${onboardingStep===0?'nature-circles':'interest-pills'}">${options.map((x,i)=>`<button type="button" class="setup-option ${picks.has(i)?'selected':''}" aria-pressed="${picks.has(i)}" ${on(()=>cloudToggleSet(picks,i))}>${onboardingStep===0?`<span>${x[0]}</span>${t(x[1],x[2])}`:t(x[0],x[1])}${picks.has(i)?' ✓':''}</button>`).join('')}</div>${onboardingStep===1?typePicker():''}`:`<label class="bio-label">${t('نبذة عنك','About you')}<textarea maxlength="160" rows="4" ${on(e=>profileBio=e.target.value.slice(0,160),'input')}>${esc(profileBio)}</textarea></label><div class="setup-avatars">${['😎','🤖','🧑‍🚀','🧙','🦊','🐼','👾','🐱'].map(x=>`<button class="chip ${profileEmoji===x&&!profilePhoto?'active':''}" ${on(()=>{profileEmoji=x;profilePhoto='';render()})}>${x}</button>`).join('')}</div><label class="file-button">${t('إضافة صورة شخصية','Add profile photo')}<input type="file" accept="image/jpeg,image/png,image/webp" ${on(e=>cloudChoosePhoto(e,0),'change')}></label>`}<div class="setup-navigation"><button class="chip" ${on(()=>{if(onboardingStep>0){onboardingStep--;render()}})} ${onboardingStep===0?'disabled':''}>${t('رجوع','Back')}</button><button class="primary" ${cloud.busy?'disabled':''} ${on(cloudOnboardingNext)}>${cloud.busy?t('جارٍ الحفظ…','Saving…'):onboardingStep===2?t('حفظ والبدء','Save & start'):t('التالي','Next')}</button></div></section>`;};
async function cloudChoosePhoto(e,slot){const file=e.target.files?.[0];if(!file)return;if(!/^image\/(jpeg|png|webp)$/.test(file.type)||file.size>8*1024*1024)return toast(t('اختر JPG أو PNG أو WebP حتى 8MB.','Choose JPG, PNG or WebP up to 8MB.'));try{toast(t('جارٍ رفع الصورة…','Uploading photo…'));const u=await cloudAPI('upload?scope=profile&target='+cloud.user.id,'POST',file);await cloudAPI('profile-photo','POST',{slot,object_path:u.path});if(slot===0){profilePhoto=u.url;const data={emoji:profileEmoji,avatar:u.path,gallery:cloud.profileData.photos.map(x=>x.object_path),useGallery:false,link:profileLink,nature:[...vibePicks],interests:[...interestPicks],types:[...typePicks],prompts:profilePrompts};await cloudAPI('profile','PATCH',{display_name:displayName,bio:profileBio,data});}await cloudProfileBundle();toast(t('تم حفظ الصورة.','Photo saved.'));render();}catch(err){toast(cloudError(err));}}
function cloudProfileSettings(){sheetShell(()=>`<div class="modal-title"><h2>${t('إعدادات الملف الشخصي','Profile settings')}</h2></div><label class="setting-row"><span><strong>${t('الصور الذكية','Smart Photos')}</strong><small>${t('تختبر صور ملفك وتعرض الأفضل أولًا.','Continuously tests your profile photos and shows the best one first.')}</small></span><input type="checkbox" ${preferences.smartPhotos?'checked':''} ${on(e=>cloudSavePreference('smartPhotos',e.target.checked),'change')}></label><h3>${t('التحكم في الظهور','Control your visibility')} <span class="plus-badge">Vibe Plus</span></h3><label class="setting-row"><span>${t('إخفاء عمري','Hide my age')}</span><input type="checkbox" ${preferences.hideAge?'checked':''} ${on(e=>cloudSavePreference('hideAge',e.target.checked),'change')}></label><label class="setting-row"><span>${t('إخفاء المسافة','Hide my distance')}</span><input type="checkbox" ${preferences.hideDistance?'checked':''} ${on(e=>cloudSavePreference('hideDistance',e.target.checked),'change')}></label><h3>${t('المظهر','Appearance')}</h3><div class="theme-switch"><button class="chip ${preferences.appearance==='dark'?'active':''}" ${on(()=>cloudSavePreference('appearance','dark'))}>◐ ${t('داكن','Dark')}</button><button class="chip ${preferences.appearance==='light'?'active':''}" ${on(()=>cloudSavePreference('appearance','light'))}>☀ ${t('فاتح','Light')}</button></div>`);}
async function cloudSavePreference(key,value){preferences[key]=value;applyAppearance();render();try{await cloudAPI('settings','POST',preferences);}catch(e){toast(cloudError(e));}}
function cloudEditDetails(){const d=cloud.profileData.details||{};sheetShell(()=>`<h2>${t('تفاصيل ملفي','My profile details')}</h2><form ${on(async e=>{e.preventDefault();const f=new FormData(e.target);try{await cloudAPI('profile-details','POST',{living_in:f.get('living_in'),height_cm:Number(f.get('height_cm'))||null,job:f.get('job'),education:f.get('education'),basics:d.basics||{},lifestyle:d.lifestyle||{}});await cloudProfileBundle();document.querySelector('#create').close();render();}catch(err){toast(cloudError(err))}},'submit')}><label>${t('أسكن في','Living in')}<input name="living_in" maxlength="120" value="${esc(d.living_in||'')}"></label><label>${t('الطول (سم)','Height (cm)')}<input name="height_cm" type="number" min="80" max="260" value="${d.height_cm||''}"></label><label>${t('العمل','Job')}<input name="job" maxlength="120" value="${esc(d.job||'')}"></label><label>${t('التعليم','Education')}<input name="education" maxlength="160" value="${esc(d.education||'')}"></label><button class="primary">${t('حفظ التفاصيل','Save details')}</button></form>`);}
function cloudEditPrompt(){const p=cloud.profileData.prompts?.[0]||{};sheetShell(()=>`<h2>${t('سؤالي التعريفي','My prompt')}</h2><form ${on(async e=>{e.preventDefault();const f=new FormData(e.target);try{await cloudAPI('profile-prompts','POST',{prompts:[{question:f.get('question'),answer:f.get('answer')}]});await cloudProfileBundle();document.querySelector('#create').close();render();}catch(err){toast(cloudError(err))}},'submit')}><label>${t('السؤال','Prompt')}<input name="question" maxlength="160" required value="${esc(p.question||t('شيء مهم عني','Something important about me'))}"></label><label>${t('إجابتي','My answer')}<textarea name="answer" maxlength="600" required>${esc(p.answer||'')}</textarea></label><button class="primary">${t('حفظ','Save')}</button></form>`);}
function cloudPreviewProfile(){sheetShell(()=>`<article class="profile-preview-card">${cloudAvatar({display_name:displayName,data:{avatar:cloud.profileData.photos?.[0]?.object_path}})}<h2>${esc(displayName)}</h2><p>${esc(profileBio||t('أضف نبذة ليعرفك مجتمع Vibe.','Add a bio so the Vibe community can know you.'))}</p><div class="type-options">${[...interestPicks].map(i=>`<span class="profile-pill">${t(interestOptions[i][0],interestOptions[i][1])}</span>`).join('')}</div></article>`);}
profile=function(){if(!cloud.user)return cloudGate();const d=cloud.profileData.details||{},photos=cloud.profileData.photos||[],prompt=cloud.profileData.prompts?.[0],c=cloud.profileData.completion||{},score=Math.min(c.photo_count||0,6)+(c.prompt_count?1:0)+[c.living_in,c.height,c.job,c.education].filter(Boolean).length+Math.min(c.basics_count||0,5)+Math.min(c.lifestyle_count||0,5),pct=Math.round(score/21*100),verified=!!((cloudPerson(cloud.user.id).data||{}).verified),missing=Math.max(0,6-photos.length);const pills=[[t('أسكن في +','Living in +'),d.living_in],[t('الطول +','Height +'),d.height_cm&&d.height_cm+' cm'],[t('العمل +','Job +'),d.job],[t('التعليم +','Education +'),d.education],[t('الأساسيات +','Basics +'),Object.keys(d.basics||{}).length],[t('نمط الحياة 4/5','Lifestyle 4/5'),Object.keys(d.lifestyle||{}).length]];return `<section class="profile-v2"><header class="profile-v2-header"><div class="profile-identity">${cloudAvatar({display_name:displayName,data:{avatar:photos[0]?.object_path}})}<div><h1>${esc(displayName)} ${verified?'<span class="verified" title="Verified">✓</span>':''}</h1><small>${esc(cloud.user.email||'')}</small></div></div><div class="profile-header-actions"><button class="icon-only" aria-label="${t('إعدادات الملف','Profile settings')}" ${on(cloudProfileSettings)}>⚙</button><button class="chip" ${on(cloudPreviewProfile)}>${t('معاينة','Preview')} ›</button></div></header><div class="completion-banner"><span>⚠</span><div><strong>${t('أكمل ملفك الشخصي','Complete your profile')}</strong><p>${t('التفاصيل الكاملة تساعد الأشخاص المناسبين على معرفتك.','Complete details help the right people get to know you.')}</p></div><b>${pct}%</b><progress max="100" value="${pct}"></progress></div><div class="attribute-strip">${pills.map(([label,value])=>`<button ${on(cloudEditDetails)} class="attribute-pill ${value?'done':'missing'}">${esc(value||label)}${value?'':'<i></i>'}</button>`).join('')}</div><section class="profile-section"><div class="section-title"><div><h2>${t('صوري','My Photos')} ${missing?'<span class="alert-dot"></span>':''}</h2><small>${missing?t(`أضف ${missing} صور إضافية`,`Add ${missing} more photos`):t('مكتملة','Complete')}</small></div></div><div class="profile-photo-grid">${[0,1,2,3,4,5].map(slot=>{const row=photos.find(x=>x.slot===slot);return `<label class="photo-slot ${slot===0?'primary-photo':''}">${row?`<img src="${esc(cloudFile(row.object_path))}" alt="">`:`<span>＋</span>`}<input type="file" accept="image/jpeg,image/png,image/webp" ${on(e=>cloudChoosePhoto(e,slot),'change')}></label>`}).join('')}</div><div class="photo-promo"><span>✦ ${t('احصل على إعجابات أكثر بملف مكتمل من 6 صور','Get up to 2x more Likes with 6 pics')}</span><button class="edit-pill" ${on(()=>document.querySelector('.photo-slot input')?.click())}>${t('تعديل','Edit')}</button></div></section><div class="profile-two-col"><section class="profile-section"><div class="section-title"><h2>${t('أسئلتي','My Prompts')}</h2><button class="icon-only" ${on(cloudEditPrompt)}>＋</button></div>${prompt?`<article class="prompt-card"><small>${esc(prompt.question)}</small><p>${esc(prompt.answer)}</p><button ${on(cloudEditPrompt)}>✎</button></article>`:`<button class="empty-prompt" ${on(cloudEditPrompt)}>＋<strong>${t('اختر سؤالًا','Select a prompt')}</strong><span>${t('أجب ليعرفك الآخرون','Answer prompt')}</span></button>`}</section><section class="profile-section"><h2>${t('اهتماماتي','My Interests')}</h2><div class="interest-card"><strong>${t('مهتم حاليًا','Currently Into')}</strong><div class="type-options">${[...interestPicks].slice(0,6).map(i=>`<span class="profile-pill">${t(interestOptions[i][0],interestOptions[i][1])}</span>`).join('')||`<span class="muted">${t('أضف اهتماماتك','Add interests')}</span>`}</div></div><div class="spotify-card"><span class="spotify-dot"></span><div><strong>${t('أستمع إلى','Listening to')}</strong><small>${t('اختر أغانيك · ربط Spotify غير مفعّل بعد','Choose Songs · Spotify connection is not enabled yet')}</small></div></div></section></div></section>`;};
function cloudUnread(id){return cloud.notifications.filter(x=>x.actor_id===id&&!x.read_at).length;}
const cloudOldOpenPeer=cloudOpenPeer;cloudOpenPeer=async function(id){try{await cloudAPI('notifications','PATCH',{actor_id:id});cloud.notifications.forEach(x=>{if(x.actor_id===id)x.read_at=new Date().toISOString()});}catch{}return cloudOldOpenPeer(id);};
async function cloudReact(id,active){try{await cloudAPI('reaction?message='+id,active?'DELETE':'POST');await cloudMessages();render();}catch(e){toast(cloudError(e));}}
cloudMessageList=function(){let lastDay='';return `<div class="messages premium-messages">${cloud.older?`<button class="chip" ${on(async()=>{await cloudMessages(true);render()})}>${t('رسائل أقدم','Older messages')}</button>`:''}${cloud.messages.map(m=>{const mine=m.author_id===cloud.user.id,day=new Date(m.created_at).toLocaleDateString(lang,{day:'numeric',month:'short',year:'numeric'}),heart=(m.message_reactions||[]).some(x=>x.user_id===cloud.user.id);const divider=day!==lastDay?`<div class="message-date">${esc(day)}</div>`:'';lastDay=day;return `${divider}<div class="message-line ${mine?'mine':''}">${!mine?cloudAvatar(cloudPerson(m.author_id)):''}<article class="bubble ${mine?'self':''}" ${on(()=>cloudReact(m.id,heart),'dblclick')}>${m.kind==='text'?`<p>${linkMessage(m.body)}</p>`:m.kind==='photo'?`<img class="chat-photo" src="${esc(cloudFile(m.object_path))}" alt="">`:`<audio controls preload="none" src="${esc(cloudFile(m.object_path))}"></audio>`}<small>${esc(new Date(m.created_at).toLocaleTimeString(lang,{hour:'2-digit',minute:'2-digit'}))}${mine?' · '+t('تم الإرسال','Sent'):''}</small>${(m.message_reactions||[]).length?`<button class="reaction ${heart?'active':''}" ${on(()=>cloudReact(m.id,heart))}>❤️ ${(m.message_reactions||[]).length}</button>`:`<span class="double-tap">${t('انقر مرتين ❤️','Double tap ❤️')}</span>`}</article></div>`}).join('')||`<p class="muted">${t('ابدأ أول رسالة.','Start the conversation.')}</p>`}</div>`;};
chats=function(){if(!cloud.user)return cloudGate();const peer=cloud.peer&&cloudPerson(cloud.peer);return `<section class="chat-v2"><div class="new-people"><h2>${t('أعضاء جدد','New members')}</h2><div>${cloud.people.slice(0,8).map(p=>`<button ${on(()=>cloudOpenPeer(p.id))}>${cloudAvatar(p)}<small>${esc(p.display_name)}</small></button>`).join('')}</div></div><div class="message-panel chat-layout"><aside class="chat-list">${cloud.people.filter(p=>!cloud.blocks.includes(p.id)).map(p=>{const n=cloudUnread(p.id),last=cloud.inbox.find(m=>m.author_id===p.id||m.recipient_id===p.id);return `<button class="chat-item ${cloud.peer===p.id?'active':''}" ${on(()=>cloudOpenPeer(p.id))}>${cloudAvatar(p)}<span><strong>${esc(p.display_name)}</strong><small>${esc((last?.body||p.bio||'').slice(0,55))}</small></span>${n?`<b class="unread-badge">${n}</b>`:''}</button>`}).join('')}</aside><div class="conversation">${peer?`<header class="chat-header"><button class="icon-only mobile-chat-back" ${on(()=>{cloud.peer=null;render()})}>‹</button><div>${cloudAvatar(peer)}<strong>${esc(peer.display_name)}</strong></div><button class="icon-only" ${on(()=>openReport('user',peer.id))}>•••</button></header>${cloudMessageList()}${sendForm('sendChat')}${cloudMediaStatus()}`:`<div class="empty-conversation"><span>✦</span><h2>${t('اختر محادثة','Choose a conversation')}</h2></div>`}</div></div></section>`;};
cloudBoot();
